const ac = A.accent;
A.bg('#05101a', '#0a2233');
const kC = A.k('Chile', 0), kRes = A.k('reservas', 1.667), kAg = A.k('agua', 2.333), kDul = A.k('dulce', 2.667);
const kGr = A.k('grandes', 3.333), kPl = A.k('planeta…', 4.0), kCo = A.k('congelada.', 4.333);

// ---------- CHILE ----------
const west = [[300,440],[296,520],[291,600],[286,680],[280,760],[271,840],[262,920],[250,990],[236,1050],[220,1100]];
const east = [[332,440],[336,520],[334,600],[328,680],[322,760],[319,840],[316,920],[311,990],[298,1050],[268,1100]];
const chile = west.concat(east.slice().reverse());
const pCh = A.p(kC, 1.0, 'snapSettle');
const dim = 1 - 0.45 * A.p(kAg + 0.3, 0.8, 'softInOut');
A.with(() => {
  if (pCh > 0.6) A.lib.hatch(ctx, chile, {angle: 0.8, spacing: 9, width: 1.5, color: ac});
  A.lib.inkPath(ctx, chile, {width: 4, color: A.pal.lineWhite, closed: true, fill: 'rgba(77,208,225,0.18)', draw: pCh});
  // Patagonia ice field
  const pIce = A.p(kC + 0.6, 0.6, 'softLand');
  A.circle(282, 985, 26 * pIce, {fill: '#e8fbff', alpha: 0.85});
  A.circle(272, 1040, 18 * pIce, {fill: '#e8fbff', alpha: 0.85});
}, {alpha: dim});
const pLab = A.p(kC + 0.25, 0.5, 'softLand');
A.text('CHILE', 375, 500, {size: 54, color: '#ffffff', weight: 800, align: 'left', alpha: pLab * dim});
A.line([[345, 488], [368, 488]], {stroke: '#ffffff', lw: 3, alpha: pLab * dim, progress: pLab});

// Patagonia pulse
if (t > kRes) {
  A.rings(280, 1010, kRes, {count: 3, speed: 160, gap: 0.35, maxR: 140, color: ac, lw: 4, alpha: 0.9 * (1 - A.p(kAg + 0.4, 0.5))});
  const pp = A.pop(kRes, 0.45);
  A.lib.glowDot(ctx, 280, 1010, 14 * pp, {color: ac});
}

// ---------- DROP ----------
const pMove = A.p(kAg, 0.7, 'whip');
const pGrow1 = A.p(kAg, 0.7, 'snapSettle');
const pGrow2 = A.p(kGr, 0.5, 'popOver');
const ice = A.p(kCo, 0.35, 'crashIn');
let dx = A.lerp(280, 690, pMove), dy = A.lerp(1010, 800, pMove);
dy += Math.sin(t * 2.2) * 6 * pMove;
let r = 18 + 102 * pGrow1 + 55 * pGrow2;
r *= 1 + 0.025 * Math.sin(t * 7) * (1 - ice);
function dropPath(x, y, R) {
  ctx.beginPath();
  ctx.moveTo(x, y - 1.7 * R);
  ctx.bezierCurveTo(x + 0.35 * R, y - 1.1 * R, x + R, y - 0.6 * R, x + R, y);
  ctx.arc(x, y, R, 0, Math.PI);
  ctx.bezierCurveTo(x - R, y - 0.6 * R, x - 0.35 * R, y - 1.1 * R, x, y - 1.7 * R);
  ctx.closePath();
}
if (t >= kAg) {
  const shake = (t > kGr && t < kGr + 0.3 ? 8 : 0) + (t > kCo && t < kCo + 0.35 ? 14 : 0);
  if (t > kGr) A.rings(dx, dy, kGr, {count: 2, speed: 420, gap: 0.2, maxR: 330, color: ac, lw: 5, alpha: 0.6});
  A.with(() => {
    // water
    const g = ctx.createLinearGradient(dx, dy - 1.7 * r, dx, dy + r);
    g.addColorStop(0, '#7fe6f2'); g.addColorStop(1, '#0b6f8a');
    ctx.save(); ctx.shadowColor = ac; ctx.shadowBlur = 40;
    dropPath(dx, dy, r); ctx.fillStyle = g; ctx.fill(); ctx.restore();
    // ice overlay
    if (ice > 0) {
      ctx.save(); dropPath(dx, dy, r); ctx.clip();
      const gi = ctx.createLinearGradient(dx - r, dy - 1.7 * r, dx + r, dy + r);
      gi.addColorStop(0, '#ffffff'); gi.addColorStop(1, '#8fdcea');
      ctx.globalAlpha = ice; ctx.fillStyle = gi; ctx.fillRect(dx - 2 * r, dy - 2 * r, 4 * r, 4 * r);
      // facets
      ctx.globalAlpha = 1;
      const fr = A.rand(7);
      const cx0 = dx + 0.15 * r, cy0 = dy - 0.2 * r;
      for (let i = 0; i < 9; i++) {
        const a = i / 9 * Math.PI * 2 + fr() * 0.4;
        const L = r * 2 * ice;
        A.line([[cx0, cy0], [cx0 + Math.cos(a) * L * 0.5, cy0 + Math.sin(a) * L * 0.5], [cx0 + Math.cos(a + 0.3) * L, cy0 + Math.sin(a + 0.3) * L]], {stroke: '#3aa9c0', lw: 3, alpha: 0.7, progress: ice});
      }
      ctx.restore();
    }
    // outline + highlight
    dropPath(dx, dy, r); ctx.lineWidth = 5; ctx.strokeStyle = ice > 0.5 ? '#ffffff' : '#bff4fa'; ctx.stroke();
    ctx.beginPath(); ctx.ellipse(dx - 0.45 * r, dy - 0.25 * r, 0.12 * r, 0.3 * r, 0.4, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.65)'; ctx.fill();
  }, {x: dx, y: dy, shake: shake, scale: 1 + 0.06 * Math.sin(Math.PI * A.p(kCo, 0.3, 'cruise'))});
}
A.flash(kCo, 0.25, 0.5);

// frost crystals after freeze
if (t > kCo) {
  A.particles(26, 11, (i, rnd) => {
    const a = rnd() * Math.PI * 2, sp = 120 + rnd() * 260;
    const tt = t - kCo;
    const px = dx + Math.cos(a) * (r * 0.9 + sp * tt), py = dy - 0.3 * r + Math.sin(a) * (r * 0.9 + sp * tt) + 40 * tt * tt;
    const s = 6 + rnd() * 8, al = A.clamp(1 - tt * 1.2);
    for (let k = 0; k < 3; k++) {
      const b = k * Math.PI / 3 + tt * 2;
      A.line([[px - Math.cos(b) * s, py - Math.sin(b) * s], [px + Math.cos(b) * s, py + Math.sin(b) * s]], {stroke: '#e8fbff', lw: 2, alpha: al});
    }
  });
}

// label swap AGUA DULCE -> HIELO
const sDul = A.pop(kDul, 0.45) * (1 - A.p(kCo, 0.15, 'accelExit'));
if (sDul > 0.01) A.label('AGUA DULCE', 690, 1085, {size: 50, bg: ac, color: '#05101a', scale: sDul});
if (t > kCo + 0.1) A.label('HIELO', 690, 1085, {size: 60, bg: '#ffffff', color: '#05101a', scale: A.pop(kCo + 0.1, 0.4)});

// ---------- GLOBE (secondary zone) ----------
if (t > kPl - 0.1) {
  const gs = A.pop(kPl - 0.1, 0.5);
  const gx = 540, gy = 1530, gr = 140;
  A.with(() => {
    A.circle(gx, gy, gr, {fill: '#0b2a3d', stroke: A.pal.lineWhite, lw: 4});
    ctx.save(); ctx.beginPath(); ctx.arc(gx, gy, gr, 0, Math.PI * 2); ctx.clip();
    for (let i = 0; i < 6; i++) {
      const ph = ((i / 6) + t * 0.15) % 1;
      const w = Math.abs(Math.cos(ph * Math.PI)) * gr;
      ctx.beginPath(); ctx.ellipse(gx, gy, w, gr, 0, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(191,244,250,0.35)'; ctx.lineWidth = 2; ctx.stroke();
    }
    for (let j = -2; j <= 2; j++) {
      ctx.beginPath(); ctx.moveTo(gx - gr, gy + j * 45); ctx.lineTo(gx + gr, gy + j * 45); ctx.stroke();
    }
    ctx.restore();
    A.lib.glowDot(ctx, gx - 50, gy + 70, 12 + 3 * Math.sin(t * 10), {color: ac});
    A.rings(gx - 50, gy + 70, kPl, {count: 2, speed: 90, gap: 0.3, maxR: 60, color: ac, lw: 3});
  }, {x: gx, y: gy, scale: gs});
  A.text('DE LAS MAYORES DEL MUNDO', gx, 1725, {size: 34, color: '#ffffff', weight: 700, align: 'center', alpha: A.p(kPl + 0.1, 0.4, 'softLand')});
}

const {W,H}=A; const ctx2=ctx;
A.bg('#0b1a33','#040a16');
const kPat=A.k('Patagonia',0.667), kDos=A.k('dos',1.333), kEn=A.k('enormes',1.667), kMan=A.k('mantos',2.0), kHie=A.k('hielo:',2.667);
const kN=A.k('Norte',4.333), kS=A.k('Sur.',6.333);
const ACC=A.accent||'#FFD400';
const ICE='#dff3ff';
// cámara: deriva lenta y paneo al sur tras "Norte"
const pan=A.p(kN+0.6,1.2,'glide');
const camY=A.lerp(0,-60,pan);
const camS=A.lerp(1.0,1.06,A.clamp(t/A.dur))+0.03*A.p(kS,0.5,'softLand');
const shake=(t>kS&&t<kS+0.35)?10*(1-(t-kS)/0.35):0;
A.with(()=>{
  // ---- costa con fiordos ----
  const r=A.rand(7); const coast=[];
  for(let i=0;i<=44;i++){const y=400+i*17; const south=i/44; const x=470+Math.sin(i*0.5)*14-south*40+(r()-0.5)*(10+south*46); coast.push([x,y]);}
  const land=coast.concat([[1000,1150],[1000,400]]);
  const pl=A.p(kPat,1.0,'softInOut');
  ctx.save(); ctx.globalAlpha=0.85*pl; ctx.beginPath(); land.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.fillStyle='#16284a'; ctx.fill(); ctx.restore();
  if(pl>0) A.lib.hatch(ctx,land,{angle:-0.6,spacing:26,width:1,color:'rgba(150,190,255,0.10)'});
  A.line(coast,{stroke:'#bcd6ff',lw:4,progress:A.p(kPat,1.1,'glide')});
  // océano
  A.text('PACÍFICO',250,800,{size:34,color:'#6f8fc4',weight:'700',align:'center',alpha:0.8*A.p(kPat+0.5,0.6)});
  // frontera / cordillera
  const pb=A.p(kPat+0.4,1.0,'glide');
  A.line([[760,410],[740,600],[770,800],[730,1000],[750,1130]],{stroke:'#6f8fc4',lw:3,dash:[14,12],progress:pb,alpha:0.7});
  const rm=A.rand(3);
  for(let i=0;i<14;i++){const mx=600+rm()*120, my=440+i*48+rm()*20; const pa=A.p(kPat+0.3+i*0.04,0.4,'softLand'); if(pa<=0)continue;
    A.line([[mx-18,my+14],[mx,my-16*pa],[mx+18,my+14]],{stroke:'#8fb0e0',lw:2.5,alpha:0.6*pa});}
  // ---- campos de hielo ----
  function blob(cx,cy,rx,ry,seed,sc){const rr=A.rand(seed);const pts=[];for(let i=0;i<28;i++){const a=i/28*Math.PI*2;const n=0.8+rr()*0.35;pts.push([cx+Math.cos(a)*rx*n*sc,cy+Math.sin(a)*ry*n*sc]);}return pts;}
  const grow=A.lerp(0.55,1,A.p(kEn,0.7,'snapSettle'));
  const fields=[{cx:575,cy:560,rx:48,ry:72,seed:11,k:kDos,hk:kN,name:'NORTE',lx:860,ly:540},
                {cx:555,cy:870,rx:62,ry:200,seed:23,k:kDos+0.15,hk:kS,name:'SUR',lx:860,ly:880}];
  fields.forEach((f,idx)=>{
    const pp=A.pop(f.k,0.45); if(pp<=0.001)return;
    const hl=A.p(f.hk,0.4,'snapSettle');
    const dim=(idx===0&&t>kS)?0.75:1;
    const extra=idx===1?A.pop(kS,0.5)*0.0+1+0.06*Math.sin(A.p(kS,0.5,'popOver')*Math.PI):1;
    const pts=blob(f.cx,f.cy,f.rx,f.ry,f.seed,pp*grow*extra);
    ctx.save(); ctx.globalAlpha=dim; ctx.shadowColor=hl>0?ACC:'#bfe8ff'; ctx.shadowBlur=20+30*hl;
    ctx.beginPath(); pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.fillStyle=ICE; ctx.fill(); ctx.restore();
    const ph=A.p(kMan,0.6,'softLand');
    if(ph>0) A.lib.hatch(ctx,pts,{angle:0.7,spacing:14,width:2,color:'rgba(90,140,200,'+(0.45*ph)+')'});
    A.lib.inkPath(ctx,pts,{width:3+3*hl,color:hl>0?ACC:'#ffffff',closed:true});
    // destellos de hielo
    const ps=A.p(kHie,0.3);
    if(ps>0){const rs=A.rand(f.seed+5);for(let j=0;j<5;j++){const sx=f.cx+(rs()-0.5)*f.rx*1.2, sy=f.cy+(rs()-0.5)*f.ry*1.4; const tw=Math.max(0,Math.sin((t-kHie)*5+j*1.7)); A.lib.glowDot(ctx,sx,sy,3+5*tw,{color:'#ffffff'});}}
    // etiqueta
    if(hl>0){
      A.line([[f.cx+f.rx+6,f.cy],[f.lx-90,f.ly]],{stroke:ACC,lw:4,progress:hl});
      A.label(f.name,f.lx,f.ly,{size:idx?64:54,bg:ACC,color:'#0b1a33',scale:A.pop(f.hk,0.45)});
      A.rings(f.cx,f.cy,f.hk,{count:idx?3:2,speed:300,gap:0.18,maxR:idx?260:150,color:ACC,lw:4});
    }
  });
},{x:W/2,y:770,scale:camS,shake:shake});
// translate pan applied via second pass not needed; ligera señal de paneo
A.flash(kS,0.25,0.25);
// ---- comparación de superficie (zona secundaria) ----
const bx=170, maxW=740;
const pN=A.p(kN+0.1,0.9,'glide'), pS=A.p(kS,0.6,'whip');
if(pN>0){
  A.text('NORTE',bx,1395,{size:38,color:'#ffffff',weight:'800',align:'left',alpha:pN});
  A.rect(bx,1420,maxW*0.32*pN,54,{r:12,fill:'#bfe8ff'});
  A.text('≈ '+A.counter(0,4200,pN,0)+' km²',bx+maxW*0.32*pN+20,1460,{size:36,color:'#bfe8ff',weight:'700',align:'left',alpha:pN});
}
const preS=A.p(kN+1.4,0.6,'softLand');
if(preS>0){
  A.text('SUR',bx,1555,{size:44,color:ACC,weight:'900',align:'left',alpha:preS});
  A.rect(bx,1580,Math.max(8,maxW*pS),64,{r:12,fill:ACC,glow:pS>0?ACC:undefined,alpha:preS});
  if(pS>0){A.text('≈ '+A.counter(0,13000,pS,0)+' km²',bx+maxW*pS-10,1680,{size:40,color:ACC,weight:'800',align:'right',alpha:pS});
    A.label('x3',bx+maxW*pS+50,1612,{size:40,bg:'#ffffff',color:'#0b1a33',scale:A.pop(kS+0.3,0.4)});}
}
void camY; void ctx2;

const W=A.W,H=A.H,ac=A.accent;
A.bg('#06121f','#0b2236',true);
const kSur=A.k('Sur',0.33),kGr=A.k('grande',1.33),kFu=A.k('fuera',2.0),kAn=A.k('Antártica',3.0),kGl=A.k('Groenlandia,',3.67),kUna=A.k('una',4.33),kMay=A.k('mayores',5.33),kHi=A.k('hielo',6.33),kMu=A.k('mundo.',7.0);
const L=A.lib;
function fillShape(pts,fill,stroke,hatchCol,alpha){
  ctx.save();ctx.globalAlpha=alpha;
  ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();
  ctx.fillStyle=fill;ctx.fill();ctx.restore();
  if(L&&L.hatch){try{ctx.save();ctx.globalAlpha=alpha*0.6;L.hatch(ctx,pts,{angle:-0.7,spacing:14,width:2,color:hatchCol});ctx.restore();}catch(e){}}
  A.line(pts.concat([pts[0]]),{stroke:stroke,lw:5,alpha:alpha});
}
function blob(cx,cy,rx,ry,seed){const r=A.rand(seed),pts=[];const ph=[r()*6,r()*6];for(let i=0;i<28;i++){const a=i/28*Math.PI*2;const w=1+0.12*Math.sin(a*3+ph[0])+0.07*Math.sin(a*5+ph[1]);pts.push([cx+Math.cos(a)*rx*w,cy+Math.sin(a)*ry*w]);}return pts;}
function surPts(cx,cy,s){const pts=[],N=22,Hh=280*s,ww=70*s;const left=[],right=[];for(let i=0;i<=N;i++){const v=i/N*2-1;const yy=cy+v*Hh;const off=Math.sin(v*3.2)*ww*0.5;const hw=ww*(0.55+0.35*Math.sin(v*7+1)*0.5+0.3*(1-Math.abs(v)))*(1-Math.pow(Math.abs(v),4)*0.7);left.push([cx+off-hw,yy]);right.push([cx+off+hw,yy]);}return left.concat(right.reverse());}
// podium geometry
const pods=[{x:250,h:200,n:'2',name:'GROENLANDIA',t:kGl},{x:540,h:270,n:'1',name:'ANTÁRTICA',t:kAn},{x:830,h:140,n:'3',name:'HIELO SUR',t:kUna+0.6}];
const podP=A.p(kFu,0.7,'snapSettle');
const glow3=A.p(kMay,0.5,'crashIn');
let shake=0;
[kAn,kGl].forEach(k=>{if(t>k+0.25&&t<k+0.6)shake=Math.max(shake,12*(1-(t-k-0.25)/0.35));});
if(t>kMay&&t<kMay+0.35)shake=Math.max(shake,8*(1-(t-kMay)/0.35));
A.with(()=>{
  // podium
  if(podP>0){pods.forEach((p,i)=>{const pp=A.clamp(A.p(kFu+i*0.12,0.7,'snapSettle'));const h=p.h*pp;const top=1120-h;
    const is3=i==2;const col=is3&&glow3>0?ac:'#e8f4ff';
    A.rect(p.x-120,top,240,h,{r:10,fill:is3&&glow3>0?'rgba(124,252,0,'+(0.18*glow3)+')':'rgba(232,244,255,0.07)',stroke:col,lw:4,glow:is3&&glow3>0?20*glow3:0});
    if(h>70){const np=is3?A.pop(kMay,0.5):pp;A.text(p.n,p.x,top+h*0.55+10,{size:is3?90:80,color:col,weight:'900',align:'center',alpha:A.clamp(pp*1.5-0.5)});
      if(is3&&glow3>0){A.with(()=>A.text('3',p.x,top+h*0.55+10,{size:90,color:ac,weight:'900',align:'center'}),{x:p.x,y:top+h*0.5,scale:np});}}
    const la=A.p(p.t+0.15,0.5,'softLand');
    A.text(p.name,p.x,1395+(1-la)*30,{size:40,color:is3?ac:'#ffffff',weight:'800',align:'center',alpha:la});
  });}
  // Antarctica
  const an=A.p(kAn,0.45,'crashIn');
  if(an>0){const y=A.lerp(300,1120-270-115,an);const sq=1+0.18*Math.max(0,1-Math.abs(t-kAn-0.45)/0.2)*(t>kAn+0.35?1:0);
    A.with(()=>fillShape(blob(540,y,135,105,3),'#eaf6ff','#ffffff','#7fb6d9',1),{x:540,y:y+105,scale:1});
    if(t>kAn+0.4)A.rings(540,1120-270,kAn+0.42,{count:2,maxR:220,color:'#ffffff',lw:3,alpha:0.6});}
  // Greenland
  const gl=A.p(kGl,0.45,'crashIn');
  if(gl>0){const y=A.lerp(300,1120-200-95,gl);fillShape(blob(250,y,80,95,9),'#dcefff','#ffffff','#7fb6d9',1);
    if(t>kGl+0.4)A.rings(250,1120-200,kGl+0.42,{count:2,maxR:160,color:'#ffffff',lw:3,alpha:0.6});}
  // Sur (hero)
  const ap=A.p(kSur,0.6,'snapSettle');
  if(ap>0){
    const grow=A.p(kGr,0.5,'popOver');
    const sh=A.p(kFu,0.6,'glide');const mv=A.p(kUna,0.7,'whip');
    let s=A.lerp(0.75,1.0,grow);s=A.lerp(s,0.42,sh);s=A.lerp(s,0.3,mv);
    let x=A.lerp(540,960,sh);x=A.lerp(x,830,mv);
    let y=A.lerp(770,560,sh);y=A.lerp(y,1120-140-90,mv);
    const bob=(t>kFu&&t<kUna)?Math.sin(t*3)*8:0;
    A.with(()=>{
      const pts=surPts(x,y+bob,s);
      if(glow3>0)A.circle(x,y,110,{fill:'rgba(124,252,0,0.12)',glow:30*glow3});
      fillShape(pts,'rgba(124,252,0,0.28)',ac,ac,1);
    },{x:x,y:y,scale:A.pop(kSur,0.5)});
    if(t>kGr)A.rings(540,770,kGr,{count:3,maxR:420,color:ac,lw:4,alpha:A.clamp(1-sh*2)});
    const la=A.clamp(A.p(kSur+0.3,0.5,'softLand')-sh*2);
    if(la>0){A.label('CAMPO DE HIELO SUR',540,1420,{size:44,bg:ac,color:'#06121f',alpha:la,scale:A.lerp(0.8,1,la)});
      const gp=A.p(kGr,0.4,'popOver');if(gp>0)A.text('ENORME',540,1530,{size:64,color:'#fff',weight:'900',align:'center',alpha:la*gp});}
    if(sh>0&&mv<1){const fp=A.clamp(A.p(kFu+0.2,0.5,'softLand')-mv);A.text('FUERA DE…',960,920,{size:38,color:ac,weight:'800',align:'center',alpha:fp});}
  }
  if(t>kMay)A.rings(830,880,kMay,{count:3,maxR:260,color:ac,lw:4,alpha:0.8});
},{shake:shake});
A.flash(kAn+0.42,0.25,0.25);A.flash(kMay,0.3,0.3);
// final tag
const fp=A.p(kHi,0.5,'snapSettle');
if(fp>0){A.with(()=>A.label('3ª MAYOR DEL MUNDO',540,1560,{size:56,bg:ac,color:'#06121f'}),{x:540,y:1560,scale:A.pop(kHi,0.5)});}
if(t>kMu){A.rings(540,1560,kMu,{count:1,maxR:420,color:ac,lw:3,alpha:0.5});}
// ambient snow
A.particles(40,7,(i,r)=>{const x=r()*W,sp=30+r()*50;const y=420+((r()*700+t*sp)%720);A.circle(x+Math.sin(t+i)*10,y,2+r()*3,{fill:'#ffffff',alpha:0.25});});

const W=A.W,H=A.H,ac=A.accent;
A.bg('#0a1a2e','#050d18');
