  // nieve leve
  for(let i=0;i<40;i++){const r=A.rand(i+50);const x=(r()*1200+t*20)%1080;const y=420+((r()*700+t*(40+r()*40))%480);A.circle(x,y,2+r()*2,{fill:'#dfefff',alpha:0.35});}
  // glaciar principal
  const gl=[[0,560],[120,520],[260,545],[380,525],[440,555],[440,860],[560,860],[560,1120],[0,1120]];
  ctx.fillStyle='#a9d3ec';ctx.beginPath();gl.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fill();
  A.lib.hatch(ctx,[[0,700],[440,700],[440,860],[560,860],[560,1120],[0,1120]],{angle:-0.7,spacing:16,width:2,color:'#6fa3c7'});
  A.lib.inkPath(ctx,gl,{width:4,color:'#eaf6ff',closed:true});
  // trozo
  const cp=A.p(kD-0.1,0.55,'cruise');
  const pf=A.p(kC,0.7,'gentleIn');
  let rot=A.lerp(0,1.5708,pf), cx=A.lerp(500,700,pf), cy=A.lerp(712,WL+20,pf)-Math.sin(pf*Math.PI)*30;
  if(t<kC&&t>kD) rot+=0.025*Math.sin(t*40)*A.p(kD,0.4);
  if(t>=ti){const d=t-ti;const pb=A.p(ti,1.4,'softLand');cy=A.lerp(WL+20,WL+35,pb)+26*Math.sin(d*5)*Math.exp(-d*1.3);cx=A.lerp(700,760,A.p(ti,2.2,'glide'));rot=1.5708+0.12*Math.sin(d*4)*Math.exp(-d*1.1);}
  const ch=[[-60,-152],[60,-137],[60,148],[-60,148]];
  A.with(()=>{
    ctx.save();ctx.translate(cx,cy);ctx.rotate(rot);
    ctx.fillStyle='#c4e4f6';ctx.beginPath();ch.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fill();
    A.lib.hatch(ctx,[[-60,40],[60,40],[60,148],[-60,148]],{angle:0.8,spacing:14,width:2,color:'#7fb1d2'});
    const hl=A.p(kT,0.4,'softLand')*(1-A.p(kC,0.4,'softInOut'));
    if(hl>0){ctx.strokeStyle=A.accent;ctx.lineWidth=7;ctx.globalAlpha=hl*(0.6+0.4*Math.sin(t*10));ctx.stroke();ctx.globalAlpha=1;}
    if(cp>=1) A.lib.inkPath(ctx,ch,{width:4,color:'#eaf6ff',closed:true});
    ctx.restore();
  });
  // grieta
  if(t<kC+0.15) A.line([[442,560],[455,620],[432,680],[452,740],[436,800],[444,860],[500,866],[560,860]],{stroke:A.accent,lw:7,progress:cp,alpha:1-A.p(kC,0.15)});
  // agua
  const wg=ctx.createLinearGradient(0,WL,0,1120);wg.addColorStop(0,'rgba(20,90,140,0.72)');wg.addColorStop(1,'rgba(6,30,60,0.92)');
  ctx.fillStyle=wg;ctx.beginPath();ctx.moveTo(0,WL);
  for(let x=0;x<=1080;x+=20){const amp=4+(t>ti?14*Math.exp(-(t-ti)*1.5)*Math.exp(-Math.abs(x-cx)/250):0);ctx.lineTo(x,WL+amp*Math.sin(x*0.03-t*4));}
  ctx.lineTo(1080,1120);ctx.lineTo(0,1120);ctx.closePath();ctx.fill();
  A.line([[560,WL],[1080,WL]],{stroke:'#8fd0ff',lw:3,alpha:0.6});
  // ondas elípticas
  for(let j=0;j<3;j++){const d=t-ti-j*0.22;if(d>0&&d<1.6){const rx=40+d*380;ctx.strokeStyle='#eaf6ff';ctx.globalAlpha=0.8*(1-d/1.6);ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(700,WL,rx,rx*0.12,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;}}
  // salpicadura
  const d=t-ti;
  if(d>0&&d<1.3){for(let i=0;i<30;i++){const r=A.rand(i+300);const vx=(r()-0.5)*700, vy=500+r()*700;const x=700+(r()-0.5)*120+vx*d, y=WL-vy*d+900*d*d;if(y<WL+5)A.circle(x,y,5+r()*7,{fill:'#dff3ff',alpha:1-d/1.3});}}
  // arcos de estruendo
  for(let j=0;j<3;j++){const e=t-kE-j*0.15;if(e>0&&e<1){const r=80+e*320;ctx.strokeStyle=A.accent;ctx.lineWidth=8;ctx.globalAlpha=1-e;ctx.beginPath();ctx.arc(700,WL-40,r,-Math.PI*0.85,-Math.PI*0.15);ctx.stroke();ctx.globalAlpha=1;}}
},{x:540,y:800,scale:zoom,shake:sh});
A.flash(ti,0.25,0.55);
// etiquetas: ESTRUENDO -> TÉMPANO
if(t>kE&&t<kN+0.1){A.label('¡ESTRUENDO!',760,560,{size:72,bg:A.accent,color:'#fff',scale:A.pop(kE,0.4)*(1-A.p(kN-0.05,0.15,'accelExit')),alpha:1});}
if(t>=kN){const s=A.pop(kN,0.45);
