const W=A.W, pal=A.pal||{};
const RED=A.accent, ICE='#BFE6FF', CYAN='#5FD3FF';
A.bg('#071426','#0B2240',true);
const kRet=A.k('retrocede',2.0), kCal=A.k('calentamiento',3.0), kAun=A.k('aunque',3.667), kUnos=A.k('unos',4.0), kPio=A.k('Pío',5.333), kAva=A.k('avanzado',6.333), kHan=A.k('han',6.0);

// ---------- ESCENA PRINCIPAL: corte del glaciar ----------
const bed=x=> x<=760 ? 500+(x-80)*0.5 : 840+(x-760)*0.9;
const water=870;
const dim = 1-0.6*A.p(kAun,0.6,'softInOut');
const intro = A.p(0,0.7,'softLand');
const breathe = Math.sin(t*1.3)*4;

function glacierPoly(front,x0,bedF,thick){
  const pts=[]; const n=24;
  for(let i=0;i<=n;i++){const x=x0+(front-x0)*i/n; const th=thick*(1-0.35*i/n); pts.push([x,bedF(x)-th]);}
  pts.push([front,bedF(front)]);
  for(let i=n;i>=0;i--){const x=x0+(front-x0)*i/n; pts.push([x,bedF(x)]);}
  return pts;
}
function fillPoly(pts,fill,alpha){ctx.save();ctx.globalAlpha=alpha;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.restore();}

A.with(()=>{
  // montaña / lecho
  const ground=[];for(let x=60;x<=1020;x+=20)ground.push([x,bed(x)]);ground.push([1020,1120],[60,1120]);
  fillPoly(ground,'#0E2A4A',1);
  try{A.lib.hatch(ctx,ground,{angle:-0.6,spacing:16,width:1.5,color:'rgba(160,200,255,0.18)'});}catch(e){}
  // lago
  const lake=[[700,water]];for(let x=700;x<=1020;x+=20)lake.push([x,Math.max(water,bed(x))]);lake.push([1020,water]);
  const wv=[];for(let x=690;x<=1020;x+=10)wv.push([x,water+Math.sin(x*0.05+t*3)*3]);
  ctx.save();ctx.beginPath();ctx.moveTo(700,water);for(let x=700;x<=1020;x+=20)ctx.lineTo(x,bed(x)>water?bed(x):water);ctx.lineTo(1020,1120);ctx.lineTo(700,1120);ctx.closePath();ctx.restore();
  fillPoly([[680,water],[1020,water],[1020,1120],[760,1120],[760,840]],'rgba(40,120,200,0.35)',1);
  A.line(wv,{stroke:CYAN,lw:3,alpha:0.8});

  // glaciar
  const pr=A.p(kRet,1.7,'glide');
  const front=A.lerp(900,540,pr);
  const ghost=glacierPoly(900,80,bed,120);
  if(pr>0.02) A.line(ghost.slice(0,26).concat([ghost[25]]),{stroke:'#ffffff',lw:3,alpha:0.5,dash:[14,12]});
  const g=glacierPoly(front,80,bed,120+breathe*0);
  const grd=ctx.createLinearGradient(0,450,0,900);grd.addColorStop(0,'#F4FBFF');grd.addColorStop(1,'#7FBCE6');
  fillPoly(g,grd,intro);
  try{A.lib.hatch(ctx,g,{angle:0.25,spacing:22,width:1.4,color:'rgba(40,90,140,0.35)'});}catch(e){}
  try{A.lib.inkPath(ctx,g,{width:4,color:'#ffffff',closed:true});}catch(e){A.line(g.concat([g[0]]),{stroke:'#fff',lw:4});}

  // flecha de retroceso
  const pa=A.p(kRet,0.5,'crashIn');
  if(pa>0){
    const fy=bed(front)-70;
    A.arrow(front+150,fy-130,front-60,fy-130,{progress:pa,color:RED,lw:12,head:34});
    A.label('RETROCEDE',front+60,fy-210,{size:50,bg:RED,color:'#fff',scale:A.pop(kRet,0.45)});
  }
  // gotas de deshielo
  if(t>kCal){
    A.particles(10,7,(i,rnd)=>{
      const per=0.9, ph=((t-kCal)+rnd()*per)%per/per;
      const x=front-10-rnd()*120, y0=bed(x)-110*(1-0.35)+10;
      const y=A.lerp(y0,y0+160,ph);
      A.drop(x,y,9,{fill:CYAN});
    });
  }
},{alpha:dim, shake: (t>kRet&&t<kRet+0.3)?6:0});

