    for(let m=-2;m<=2;m++){const rx=Math.abs(Math.cos((m*0.55+t*0.4)))*360;ctx.beginPath();ctx.ellipse(540,800,rx,360,0,0,Math.PI*2);ctx.stroke();}
    for(let p=-2;p<=2;p++){const yy=800+p*130;const rr=Math.sqrt(Math.max(0,360*360-(p*130)**2));ctx.beginPath();ctx.ellipse(540,yy,rr,rr*0.12,0,0,Math.PI*2);ctx.stroke();}
