  }

  // montaña
  A.with(()=>{
    const mtn=[[170,1060],[290,840],[370,880],[500,600],[600,710],[680,650],[790,870],[910,1060]];
    L.inkPath(ctx,mtn,{width:4,color:'#cfe0ff',closed:true,fill:'#18284d'});
